<?php
require_once __DIR__.'/layout.php';$u=require_login();$pdo=db();$studentId=(int)($_GET['student_id']??$_POST['student_id']??0);
if($u['role']==='teacher'){$st=$pdo->prepare("SELECT DISTINCT st.id,CONCAT(st.last_names,', ',st.names,' · ',se.grade_name,' ',se.section_name) label FROM students st JOIN sections se ON se.id=st.section_id JOIN teacher_assignments ta ON ta.section_id=st.section_id WHERE ta.user_id=? AND st.active=1 ORDER BY se.grade_name,se.section_name,st.order_no,st.last_names");$st->execute([$u['id']]);$students=$st->fetchAll();}else{$students=$pdo->query("SELECT st.id,CONCAT(st.last_names,', ',st.names,' · ',se.grade_name,' ',se.section_name) label FROM students st JOIN sections se ON se.id=st.section_id WHERE st.active=1 ORDER BY se.grade_name,se.section_name,st.order_no,st.last_names")->fetchAll();}
$student=null;$grades=[];$attendance=[];$status=null;$technical=[];
if($studentId){
 if($u['role']==='teacher'){$st=$pdo->prepare("SELECT st.*,se.grade_name,se.section_name,se.technical_track,se.professional_family,ay.name year_name FROM students st JOIN sections se ON se.id=st.section_id JOIN academic_years ay ON ay.id=se.academic_year_id WHERE st.id=? AND st.section_id IN (SELECT section_id FROM teacher_assignments WHERE user_id=?)");$st->execute([$studentId,$u['id']]);}
 else{$st=$pdo->prepare("SELECT st.*,se.grade_name,se.section_name,se.technical_track,se.professional_family,ay.name year_name FROM students st JOIN sections se ON se.id=st.section_id JOIN academic_years ay ON ay.id=se.academic_year_id WHERE st.id=?");$st->execute([$studentId]);}
 $student=$st->fetch();
 if($student){
   // Solo áreas curriculares usan P1-P4.
   $st=$pdo->prepare("SELECT su.id,su.name,g.period,g.score FROM subjects su LEFT JOIN grades g ON g.subject_id=su.id AND g.student_id=? WHERE su.active=1 AND su.type='curricular' AND (EXISTS(SELECT 1 FROM teacher_assignments ta WHERE ta.section_id=? AND ta.subject_id=su.id) OR EXISTS(SELECT 1 FROM grades gx WHERE gx.student_id=? AND gx.subject_id=su.id)) ORDER BY su.name");$st->execute([$studentId,$student['section_id'],$studentId]);
   foreach($st as $r){$grades[$r['id']]['name']=$r['name'];if($r['period'])$grades[$r['id']][$r['period']]=$r['score'];}
   // Módulos técnicos: RA configurados y sus calificaciones.
   $st=$pdo->prepare("SELECT su.id subject_id,su.name,lr.id ra_id,lr.ra_code,lr.title,rs.score FROM subjects su JOIN learning_results lr ON lr.subject_id=su.id LEFT JOIN ra_scores rs ON rs.learning_result_id=lr.id AND rs.student_id=? WHERE su.active=1 AND su.type='technical' AND (EXISTS(SELECT 1 FROM teacher_assignments ta WHERE ta.section_id=? AND ta.subject_id=su.id) OR EXISTS(SELECT 1 FROM ra_scores rx JOIN learning_results lx ON lx.id=rx.learning_result_id WHERE rx.student_id=? AND lx.subject_id=su.id)) ORDER BY su.name,lr.sort_order,lr.ra_code");$st->execute([$studentId,$student['section_id'],$studentId]);
   foreach($st as $r){$technical[$r['subject_id']]['name']=$r['name'];$technical[$r['subject_id']]['ras'][]=['code'=>$r['ra_code'],'title'=>$r['title'],'score'=>$r['score']];}
   $st=$pdo->prepare('SELECT * FROM attendance WHERE student_id=? ORDER BY period');$st->execute([$studentId]);$attendance=$st->fetchAll();
   $st=$pdo->prepare('SELECT * FROM student_status WHERE student_id=?');$st->execute([$studentId]);$status=$st->fetch();
 }
}
if($_SERVER['REQUEST_METHOD']==='POST'&&$student){verify_csrf();$st=$pdo->prepare("INSERT INTO student_status(student_id,status,final_condition,updated_by) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),final_condition=VALUES(final_condition),updated_by=VALUES(updated_by),updated_at=CURRENT_TIMESTAMP");$st->execute([$studentId,$_POST['status']?:null,trim($_POST['final_condition']??'')?:null,$u['id']]);flash('success','Situación final actualizada.');header('Location: reports.php?student_id='.$studentId);exit;}
app_header('Boletín de calificaciones'); ?>
<div class="panel no-print"><form method="get" class="filters"><label>Estudiante<select name="student_id" onchange="this.form.submit()"><option value="">Seleccione</option><?php foreach($students as $s):?><option value="<?=$s['id']?>" <?=$studentId==$s['id']?'selected':''?>><?=h($s['label'])?></option><?php endforeach;?></select></label><?php if($student):?><button type="button" class="button blue" onclick="window.print()">Imprimir / Guardar PDF</button><?php endif;?></form></div>
<?php if($student):?>
<div class="student-overview no-print"><div><span class="mini-kicker">ESTUDIANTE</span><h2><?=h($student['last_names'].', '.$student['names'])?></h2><p><?=h($student['grade_name'].' '.$student['section_name'])?> · Año escolar <?=h($student['year_name'])?></p><?php if($student['technical_track']):?><p><b><?=h($student['technical_track'])?></b> · <?=h($student['professional_family'])?></p><?php endif;?></div><div class="overview-actions"><a class="button gray" href="grades.php?section_id=<?=$student['section_id']?>">P1–P4</a><a class="button gray" href="modules.php?section_id=<?=$student['section_id']?>">Módulos RA</a></div></div>
<div class="panel"><div class="report-sheet">
  <div style="text-align:center"><small>Dirección General de Educación Secundaria</small><h2 class="report-title">BOLETÍN DE CALIFICACIONES</h2><b>Año escolar: <?=h($student['year_name'])?></b></div>
  <div class="report-meta"><div><b>Nombre(s) y apellido(s):</b> <?=h($student['names'].' '.$student['last_names'])?></div><div><b>Grado:</b> <?=h($student['grade_name'])?> &nbsp; <b>Sección:</b> <?=h($student['section_name'])?> &nbsp; <b>No.:</b> <?=h($student['order_no'])?></div><div><b>ID estudiante (SIGERD):</b> <?=h($student['sigerd_id'])?></div><div><b>Centro educativo:</b> Politécnico Prof. Plinio Martínez</div><?php if($student['technical_track']):?><div><b>Bachiller técnico:</b> <?=h($student['technical_track'])?></div><div><b>Familia profesional:</b> <?=h($student['professional_family'])?></div><?php endif;?></div>

  <div class="report-bar">ÁREAS CURRICULARES · P1 / P2 / P3 / P4</div>
  <table><thead><tr><th>Área curricular</th><th>P1</th><th>P2</th><th>P3</th><th>P4</th><th>Promedio</th></tr></thead><tbody><?php foreach($grades as $g):$vals=[];foreach(['P1','P2','P3','P4'] as $p)if(isset($g[$p])&&$g[$p]!==null)$vals[]=(float)$g[$p];?><tr><td><?=h($g['name'])?></td><?php foreach(['P1','P2','P3','P4'] as $p):?><td><?=h(isset($g[$p])?$g[$p]:'')?></td><?php endforeach;?><td><b><?=$vals?number_format(array_sum($vals)/count($vals),1):''?></b></td></tr><?php endforeach;?></tbody></table>

  <?php if($technical):?><div class="report-bar">MÓDULOS FORMATIVOS · RESULTADOS DE APRENDIZAJE</div>
  <?php foreach($technical as $m):?><div class="module-report"><b><?=h($m['name'])?></b><div class="table-wrap"><table class="ra-report-table"><thead><tr><?php foreach($m['ras'] as $ra):?><th title="<?=h($ra['title'])?>"><?=h($ra['code'])?></th><?php endforeach;?><th>Promedio RA</th></tr></thead><tbody><tr><?php $rvals=[];foreach($m['ras'] as $ra):if($ra['score']!==null)$rvals[]=(float)$ra['score'];?><td><?=h($ra['score']??'')?></td><?php endforeach;?><td><b><?=$rvals?number_format(array_sum($rvals)/count($rvals),1):''?></b></td></tr></tbody></table></div></div><?php endforeach;?><?php endif;?>

  <div style="display:grid;grid-template-columns:1fr 1.5fr;gap:1rem;margin-top:1rem"><div><div class="report-bar">ASISTENCIA</div><table><thead><tr><th>Período</th><th>Asistencia</th><th>Ausencia</th></tr></thead><tbody><?php foreach(['P1','P2','P3','P4'] as $p):$a=null;foreach($attendance as $x)if($x['period']===$p)$a=$x;?><tr><td><?=$p?></td><td><?=h($a['present']??'')?></td><td><?=h($a['absent']??'')?></td></tr><?php endforeach;?></tbody></table></div><div><div class="report-bar">SITUACIÓN DEL/DE LA ESTUDIANTE</div><form method="post" class="no-print"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>Situación<select name="status"><option value="">Sin definir</option><option <?=($status['status']??'')==='Promovido/a'?'selected':''?>>Promovido/a</option><option <?=($status['status']??'')==='Repitente'?'selected':''?>>Repitente</option></select></label><label>Condición final<input name="final_condition" value="<?=h($status['final_condition']??'')?>"></label><div class="actions"><button class="button">Guardar situación</button></div></form><div class="print-only"><p><b>Situación:</b> <?=h($status['status']??'')?></p><p><b>Condición final:</b> <?=h($status['final_condition']??'')?></p></div></div></div>
  <div style="display:flex;justify-content:space-around;margin-top:3.5rem;text-align:center"><span>_________________________<br>Maestro(a) encargado(a) del grado</span><span>_________________________<br>Director(a) del Centro Educativo</span></div>
</div></div>
<?php else:?><div class="panel empty">Seleccione un estudiante para generar el boletín.</div><?php endif;?>
<?php app_footer(); ?>
